-- ACTUALIZACION ADMINISTRATIVA DEL PROYECTO UNIVERSITARIO.
-- Personas, empresas, domicilios y contactos sinteticos; no son datos verificados.
-- Los telefonos tienen formato nacional de diez digitos; no se garantiza que
-- esten libres o que no coincidan con un numero asignado. No se deben contactar.
-- example.com es un dominio reservado para documentacion, no correo operativo.
-- Solo actualiza valores originales de la muestra: conserva cambios del equipo.
-- Conserva IDs, relaciones, fechas, cantidades y todo historial clinico/contable.
-- Ejecutar sobre la carga inicial + ampliacion; NO reemplaza un respaldo.
-- Detener ante el primer error y ejecutar ROLLBACK; nunca continuar a COMMIT.
SET NAMES utf8mb4;
USE hospital_universitario;
START TRANSACTION;
UPDATE `departamentos` SET `codigo`=CASE WHEN `codigo` <=> 'DEP-DEMO-01' THEN 'DEP-001' ELSE `codigo` END, `nombre`=CASE WHEN `nombre` <=> 'Consulta externa de demostracion' THEN 'Consulta externa' ELSE `nombre` END WHERE `departamento_id`=1;
